import React, { useState, useEffect, useRef, useCallback } from "react";
import { X, Menu, Trash2, LogOut, ImagePlus, Star, ChevronLeft, ChevronRight, Eye, ChevronDown, Share2, ZoomIn, ZoomOut } from "lucide-react";
import { getProducts, createProduct, deleteProduct, updateStock } from "./api";

/* ---------------------------------------------------------
   ALIF Traditional — single page React site with admin portal.
   Data lives in MongoDB Atlas via a small Express API (see /server).
   Each product can carry multiple photos + a description, and
   clicking a card opens a full gallery/detail view.
--------------------------------------------------------- */

const API_URL = import.meta.env.VITE_API_URL || "http://localhost:4000";
const MAX_PHOTOS = 8;

const CATEGORIES = [
  { id: "clothes-brand", label: "Clothes Brand", tagline: "Everyday elegance, from our own label.", alt: false },
  { id: "suits", label: "Suits", tagline: "Hand-finished silhouettes for every occasion.", alt: true },
  { id: "dupattas", label: "Dupattas", tagline: "The finishing drape, delicately detailed.", alt: false },
  { id: "shawls", label: "Shawls", tagline: "Warmth wrapped in heritage weaves.", alt: true },
  { id: "bags", label: "Bags", tagline: "Structured companions for the modern day.", alt: false },
  { id: "bedsheets", label: "Bed Sheets", tagline: "Softness woven for restful nights.", alt: true },
];

const WHATSAPP_NUMBER = "923083420221"; // replace with the real number

// Put your own video file at frontend/public/hero-video.mp4 (a short,
// looping clip works best — 10-20 seconds, under ~10MB for fast loading).
const VIDEO_SRC = "/hero-video.mp4";

// Brand emblem, embedded as base64 so the app has no external file dependency.
const LOGO_SRC = "data:image/webp;base64,";

const LOW_STOCK_THRESHOLD = 3;

function stockStatus(stock) {
  const n = Number(stock) || 0;
  if (n <= 0) return "out";
  if (n <= LOW_STOCK_THRESHOLD) return "low";
  return "in";
}

function StockBadge({ stock }) {
  const status = stockStatus(stock);
  if (status === "out") return <span className="stock-badge out">Out of Stock</span>;
  if (status === "low") return <span className="stock-badge low">Only {stock} left</span>;
  return null;
}

function Paisley({ stroke = "#E9CE8C", size = 64 }) {
  return (
    <svg viewBox="0 0 64 64" width={size} height={size} fill="none" aria-hidden="true">
      <path d="M32 6C46 6 54 18 50 30C47 40 38 48 28 46C16 44 8 34 12 22C15 12 22 6 32 6Z" stroke={stroke} strokeWidth="1.2" />
      <path d="M30 12C24 16 20 24 24 30C27 34 33 34 35 30" stroke={stroke} strokeWidth="1.2" fill="none" />
    </svg>
  );
}

function DividerPaisley({ fill, innerStroke }) {
  return (
    <svg viewBox="0 0 64 64" width="26" height="26" fill="none" aria-hidden="true">
      <path d="M32 6C46 6 54 18 50 30C47 40 38 48 28 46C16 44 8 34 12 22C15 12 22 6 32 6Z" fill={fill} />
      <path d="M30 12C24 16 20 24 24 30C27 34 33 34 35 30" stroke={innerStroke} strokeWidth="1.3" fill="none" />
    </svg>
  );
}

function Divider({ dark }) {
  return (
    <div className={"divider" + (dark ? " dark" : "")} aria-hidden="true">
      <span className="divider-line"></span>
      <DividerPaisley fill={dark ? "#E9CE8C" : "#C79A3C"} innerStroke={dark ? "#6E1F2B" : "#FBF4E7"} />
      <span className="divider-line"></span>
    </div>
  );
}

function WhatsAppIcon() {
  return (
    <svg viewBox="0 0 32 32" fill="#fff" width="30" height="30" aria-hidden="true">
      <path d="M16.02 2.67C8.65 2.67 2.67 8.65 2.67 16.02c0 2.5.68 4.83 1.87 6.84L2.67 29.33l6.63-1.83a13.3 13.3 0 0 0 6.72 1.82c7.37 0 13.35-5.98 13.35-13.3S23.39 2.67 16.02 2.67zm0 24.28c-2.14 0-4.14-.62-5.83-1.68l-.42-.25-4.4 1.21 1.19-4.3-.27-.44a10.86 10.86 0 0 1-1.7-5.87c0-6 4.9-10.9 10.93-10.9 6 0 10.9 4.9 10.9 10.9s-4.9 10.9-10.4 10.33z" />
      <path d="M22.1 19.05c-.33-.17-1.95-.96-2.26-1.07-.3-.11-.52-.17-.75.17-.22.33-.85 1.07-1.05 1.3-.19.22-.38.25-.71.08-.33-.17-1.4-.52-2.66-1.65-.98-.88-1.65-1.96-1.84-2.29-.19-.33-.02-.5.15-.67.15-.15.33-.38.5-.58.16-.19.22-.33.33-.55.11-.22.05-.42-.03-.58-.08-.17-.75-1.8-1.02-2.47-.27-.65-.55-.56-.75-.57h-.64c-.22 0-.58.08-.88.42-.3.33-1.15 1.13-1.15 2.75s1.18 3.2 1.34 3.42c.17.22 2.32 3.55 5.63 4.98.79.34 1.4.54 1.88.7.79.25 1.5.21 2.07.13.63-.1 1.95-.8 2.22-1.57.28-.77.28-1.43.19-1.57-.08-.14-.3-.22-.63-.38z" />
    </svg>
  );
}

function StarRating({ value, size = 14 }) {
  if (!value) return null;
  return (
    <div className="star-rating" aria-label={value + " out of 5 stars"}>
      {[1, 2, 3, 4, 5].map((n) => (
        <Star key={n} size={size} strokeWidth={1.5} className={n <= value ? "star filled" : "star"} />
      ))}
    </div>
  );
}

function StarPicker({ value, onChange }) {
  return (
    <div className="star-picker" role="radiogroup" aria-label="Product rating">
      {[1, 2, 3, 4, 5].map((n) => (
        <button
          key={n}
          type="button"
          role="radio"
          aria-checked={value === n}
          aria-label={n + " star" + (n > 1 ? "s" : "")}
          className={n <= value ? "star-btn filled" : "star-btn"}
          onClick={() => onChange(n === value ? 0 : n)}
        >
          <Star size={22} strokeWidth={1.5} />
        </button>
      ))}
    </div>
  );
}

function compressImage(file, maxW = 800, quality = 0.75) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const scale = Math.min(1, maxW / img.width);
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = () => reject(new Error("Could not read that image."));
      img.src = e.target.result;
    };
    reader.onerror = () => reject(new Error("Could not read that file."));
    reader.readAsDataURL(file);
  });
}

function resetForm() {
  setPTitle("");
  setPDescription("");
  setPPrice("");
  setPRating(0);
  setPStock("");
  setPMaterial("");
  setPDesign("");
  setPImages([]);
  setImageError("");
  setEditingId(null);
  if (fileInputRef.current) fileInputRef.current.value = "";
}

function startEdit(product) {
  setEditingId(product.id);
  setPCategory(product.category);
  setPTitle(product.title);
  setPDescription(product.description || "");
  setPPrice(product.price || "");
  setPRating(product.rating || 0);
  setPStock(product.stock ?? "");
  setPMaterial(product.material || "");
  setPDesign(product.design || "");
  setPImages(product.images || []); // existing photos load into the same editor —
  setImageError("");                // you can remove old ones and add new ones below
  setFormMsg(null);
  // scroll the admin form into view
  document.getElementById("adminFormTop")?.scrollIntoView({ behavior: "smooth" });
}

export default function App() {
  const [products, setProducts] = useState([]);
  const [loadingProducts, setLoadingProducts] = useState(true);
  const [loadError, setLoadError] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [mobileNavOpen, setMobileNavOpen] = useState(false);

  const [adminOpen, setAdminOpen] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);
  const [adminKey, setAdminKey] = useState("");
  const [passwordInput, setPasswordInput] = useState("");
  const [loginError, setLoginError] = useState("");
  const [loggingIn, setLoggingIn] = useState(false);

  const [pCategory, setPCategory] = useState(CATEGORIES[0].label);
  const [pTitle, setPTitle] = useState("");
  const [pDescription, setPDescription] = useState("");
  const [pPrice, setPPrice] = useState("");
  const [pRating, setPRating] = useState(0);
  const [pStock, setPStock] = useState("");
  const [pImages, setPImages] = useState([]);
  const [imageError, setImageError] = useState("");
  const [formMsg, setFormMsg] = useState(null);
  const [saving, setSaving] = useState(false);
  const fileInputRef = useRef(null);

  const [selectedProduct, setSelectedProduct] = useState(null);
  const [galleryIndex, setGalleryIndex] = useState(0);
  const [linkCopied, setLinkCopied] = useState(false);
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [zoomedIn, setZoomedIn] = useState(false);
  const carouselRefs = useRef({});

  const [pMaterial, setPMaterial] = useState("");
  const [pDesign, setPDesign] = useState("");
  const [editingId, setEditingId] = useState(null); // null = adding, otherwise id being edited

  function scrollCarousel(categoryId, dir) {
    const track = carouselRefs.current[categoryId];
    if (!track) return;
    const cardWidth = track.querySelector(".card")?.offsetWidth || 260;
    track.scrollBy({ left: dir * (cardWidth + 22) * 2, behavior: "smooth" });
  }

  const refreshProducts = useCallback(async () => {
    try {
      const list = await getProducts();
      setProducts(list);
      setLoadError(false);
    } catch (err) {
      console.error(err);
      setLoadError(true);
    } finally {
      setLoadingProducts(false);
    }
  }, []);

  useEffect(() => { refreshProducts(); }, [refreshProducts]);

  // If the URL has #product-<id> (from a shared WhatsApp link), open that product
  useEffect(() => {
    if (loadingProducts || products.length === 0) return;
    const match = window.location.hash.match(/^#product-(.+)$/);
    if (match) {
      const found = products.find((p) => String(p.id) === match[1]);
      if (found) { setSelectedProduct(found); setGalleryIndex(0); }
    }
  }, [loadingProducts, products]);

  useEffect(() => {
    function onScroll() { setScrolled(window.scrollY > 40); }
    window.addEventListener("scroll", onScroll);
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // Reveal product cards with a "curtain" animation as they scroll into view.
  // A safety-net timeout force-reveals any card that, for whatever reason
  // (browser quirk, nested scroll container, etc.), never gets an
  // intersection event — so products can never end up permanently invisible.
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0, rootMargin: "80px" }
    );
    const cards = document.querySelectorAll(".card:not(.is-visible)");
    cards.forEach((el) => observer.observe(el));

    const safetyTimer = setTimeout(() => {
      document.querySelectorAll(".card:not(.is-visible)").forEach((el) => {
        el.classList.add("is-visible");
      });
    }, 1200);

    return () => { observer.disconnect(); clearTimeout(safetyTimer); };
  }, [products, loadingProducts]);

  const scrollToId = useCallback((id) => {
    setMobileNavOpen(false);
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  }, []);

  function openAdmin() {
    setAdminOpen(true);
    setLoginError("");
    setPasswordInput("");
  }
  function closeAdmin() { setAdminOpen(false); }

  async function handleLogin() {
    setLoggingIn(true);
    setLoginError("");
    try {
      const res = await fetch(`${API_URL}/api/admin/verify`, {
        method: "POST",
        headers: { "x-admin-key": passwordInput },
      });
      if (!res.ok) throw new Error("bad key");
      setAdminKey(passwordInput);
      setIsAdmin(true);
      setPasswordInput("");
    } catch (err) {
      setLoginError("Incorrect password, or the server isn't reachable. Please try again.");
    } finally {
      setLoggingIn(false);
    }
  }
  function handleLogout() {
    setIsAdmin(false);
    setAdminKey("");
  }

  async function handleFilesChange(e) {
    const files = Array.from(e.target.files || []);
    if (!files.length) return;
    const room = MAX_PHOTOS - pImages.length;
    if (room <= 0) {
      setImageError(`You can add up to ${MAX_PHOTOS} photos per product.`);
      return;
    }
    setImageError("");
    const toProcess = files.slice(0, room);
    try {
      const compressed = await Promise.all(toProcess.map((f) => compressImage(f)));
      setPImages((prev) => [...prev, ...compressed]);
    } catch (err) {
      setImageError(err.message || "Could not process one of those images.");
    }
    if (fileInputRef.current) fileInputRef.current.value = "";
  }

  function removeImageAt(idx) {
    setPImages((prev) => prev.filter((_, i) => i !== idx));
  }

  function resetForm() {
    setPTitle("");
    setPDescription("");
    setPPrice("");
    setPRating(0);
    setPStock("");
    setPImages([]);
    setImageError("");
    if (fileInputRef.current) fileInputRef.current.value = "";
  }

  async function handleSubmit(e) {
    e.preventDefault();
    if (!pTitle.trim()) {
      setFormMsg({ type: "error", text: "Please give the product a name." });
      return;
    }
    if (pImages.length === 0) {
      setFormMsg({ type: "error", text: "Please upload at least one photo." });
      return;
    }
    setSaving(true);
    const payload = {
      category: pCategory,
      title: pTitle.trim(),
      description: pDescription.trim(),
      price: pPrice.trim(),
      rating: pRating,
      stock: pStock === "" ? 0 : Number(pStock),
      material: pMaterial.trim(),
      design: pDesign.trim(),
      images: pImages,
    };
    try {
      if (editingId) {
        await updateProduct(editingId, payload, adminKey);
        setFormMsg({ type: "success", text: "Product updated." });
      } else {
        await createProduct(payload, adminKey);
        setFormMsg({ type: "success", text: "Product added — visible to everyone now." });
      }
      resetForm();
      await refreshProducts();
      setTimeout(() => setFormMsg(null), 3000);
    } catch (err) {
      console.error(err);
      if (String(err.message).toLowerCase().includes("unauthorized")) {
        setFormMsg(null);
        setIsAdmin(false);
        setAdminKey("");
        setLoginError("Your session's password no longer matches the server. Please log in again.");
      } else {
        setFormMsg({ type: "error", text: "Couldn't save — " + err.message });
      }
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete(product) {
    try {
      await deleteProduct(product.id, adminKey);
      await refreshProducts();
      if (selectedProduct && selectedProduct.id === product.id) setSelectedProduct(null);
    } catch (err) {
      console.error("Delete failed:", err);
    }
  }

  async function handleAdjustStock(product, delta) {
    const next = Math.max(0, (Number(product.stock) || 0) + delta);
    try {
      await updateStock(product.id, next, adminKey);
      await refreshProducts();
    } catch (err) {
      console.error("Stock update failed:", err);
    }
  }

  function openDetail(product) {
    setSelectedProduct(product);
    setGalleryIndex(0);
    window.history.replaceState(null, "", `#product-${product.id}`);
  }
  function closeDetail() {
    setSelectedProduct(null);
    setLightboxOpen(false);
    setZoomedIn(false);
    window.history.replaceState(null, "", window.location.pathname);
  }
  function nextImage() {
    if (!selectedProduct) return;
    setZoomedIn(false);
    setGalleryIndex((i) => (i + 1) % selectedProduct.images.length);
  }
  function prevImage() {
    if (!selectedProduct) return;
    setZoomedIn(false);
    setGalleryIndex((i) => (i - 1 + selectedProduct.images.length) % selectedProduct.images.length);
  }
  function openLightbox() { setLightboxOpen(true); setZoomedIn(false); }
  function closeLightbox() { setLightboxOpen(false); setZoomedIn(false); }

  useEffect(() => {
    function onKey(e) {
      if (e.key === "Escape" && lightboxOpen) closeLightbox();
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [lightboxOpen]);

  function itemsFor(label) {
    return products.filter((p) => p.category === label);
  }

  return (
    <div className="alif-root">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,500;0,9..144,600;0,9..144,700;1,9..144,500;1,9..144,600&family=Jost:wght@300;400;500;600&display=swap');

        .alif-root{
          --maroon:#C4562A; --maroon-dark:#4A2515; --gold:#D9A441; --gold-light:#F0C888;
          --cream:#FBF3EA; --cream-deep:#F4E6D5; --blush:#F5E0D2; --ink:#2A1F19; --ink-soft:#6E5B4C;
          --sage:#7C8B6F; --sage-dark:#5C6B50;
          --whatsapp:#25D366;
          --radius-sm:10px; --radius-md:16px; --radius-lg:26px; --radius-pill:999px;
          --shadow-soft:0 10px 30px rgba(74,37,21,.08); --shadow-lift:0 22px 50px rgba(74,37,21,.16);
          background:var(--cream); color:var(--ink); font-family:'Jost',sans-serif; font-weight:400;
          -webkit-font-smoothing:antialiased; position:relative; overflow-x:hidden;
        }
        .alif-root *{box-sizing:border-box;}
        .alif-root h1,.alif-root h2,.alif-root h3,.serif{font-family:'Fraunces',serif;}
        .alif-root img{max-width:100%;display:block;}
        .alif-root a{color:inherit;text-decoration:none;}
        .wrap{max-width:1180px;margin:0 auto;padding:0 28px;}
        .eyebrow{font-family:'Fraunces',serif;font-style:italic;letter-spacing:.14em;text-transform:uppercase;font-size:14px;color:var(--gold);display:block;margin-bottom:8px;}
        .alif-root button{font-family:'Jost',sans-serif;cursor:pointer;}
        .alif-root :focus-visible{outline:2px solid var(--gold);outline-offset:3px;}

        header.site{position:fixed;top:0;left:0;right:0;z-index:200;padding:22px 0;transition:background .35s ease,padding .35s ease,box-shadow .35s ease,backdrop-filter .35s ease;}
        header.site .wrap{display:flex;align-items:center;justify-content:space-between;}
        header.site.scrolled{background:rgba(251,244,231,.72);backdrop-filter:blur(14px) saturate(160%);-webkit-backdrop-filter:blur(14px) saturate(160%);padding:14px 0;box-shadow:0 8px 30px rgba(43,33,29,.08);}
        .brand{display:flex;align-items:center;gap:10px;}
        .brand-logo{width:38px;height:38px;border-radius:50%;flex-shrink:0;box-shadow:0 0 0 1px rgba(217,164,65,.5);}
        header.site .brand-name{font-family:'Fraunces',serif;font-weight:600;font-size:22px;letter-spacing:.03em;color:var(--cream);transition:color .35s ease;}
        header.site.scrolled .brand-name{color:var(--maroon);}
        .brand-name em{font-style:italic;color:var(--gold);}

        nav.main-nav{display:flex;align-items:center;gap:34px;}
        nav.main-nav button.nav-link{background:none;border:none;font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:var(--cream);opacity:.9;transition:color .35s ease,opacity .2s ease;position:relative;padding:0 0 4px;font-family:inherit;}
        header.site.scrolled nav.main-nav button.nav-link{color:var(--ink);}
        nav.main-nav button.nav-link::after{content:"";position:absolute;left:0;bottom:0;width:0;height:1px;background:var(--gold);transition:width .25s ease;}
        nav.main-nav button.nav-link:hover::after{width:100%;}
        nav.main-nav button.nav-link:hover{opacity:1;}
        .nav-toggle{display:none;background:none;border:none;padding:6px;color:var(--cream);}
        header.site.scrolled .nav-toggle{color:var(--maroon);}

        @media (max-width:820px){
          nav.main-nav{position:fixed;top:0;right:0;height:100vh;width:min(78vw,320px);background:var(--maroon-dark);flex-direction:column;align-items:flex-start;gap:26px;padding:110px 34px 40px;transform:translateX(100%);transition:transform .4s ease;}
          nav.main-nav.open{transform:translateX(0);}
          nav.main-nav button.nav-link{color:var(--cream-deep)!important;}
          .nav-toggle{display:block;}
        }

        .hero{position:relative;min-height:100vh;display:flex;align-items:center;justify-content:center;text-align:center;color:var(--cream);overflow:hidden;padding:120px 24px 80px;background:var(--maroon-dark);}
        .hero-video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0;}
        .hero-scrim{position:absolute;inset:0;z-index:1;
          background:linear-gradient(180deg,rgba(42,23,14,.55) 0%,rgba(42,23,14,.35) 40%,rgba(42,23,14,.72) 100%),
                      radial-gradient(ellipse at 50% 10%,rgba(217,164,65,.2),transparent 60%);}
        .scroll-cue{position:absolute;bottom:28px;left:50%;transform:translateX(-50%);z-index:2;background:rgba(255,255,255,.12);backdrop-filter:blur(6px);border:1px solid rgba(255,255,255,.25);color:var(--cream);width:38px;height:38px;border-radius:50%;display:flex;align-items:center;justify-content:center;animation:scrollCueBounce 2.2s ease-in-out infinite;}
        @keyframes scrollCueBounce{0%,100%{transform:translate(-50%,0);}50%{transform:translate(-50%,6px);}}
        @media (prefers-reduced-motion:reduce){.scroll-cue{animation:none;}}
        .hero-inner{position:relative;z-index:2;max-width:680px;}
        .hero h1{margin:0;font-weight:600;line-height:1.02;}
        .hero p.tag{font-family:'Fraunces',serif;font-style:italic;font-size:20px;color:var(--cream-deep);margin:22px 0 34px;letter-spacing:.02em;}

        .hero-logo-float{width:170px;height:170px;margin:0 auto 22px;position:relative;animation:heroFloat 6s ease-in-out infinite;}
        .hero-logo{width:100%;height:100%;border-radius:50%;display:block;opacity:0;transform:scale(.92);animation:heroLogoIn 1.1s cubic-bezier(.22,.61,.36,1) forwards .2s;box-shadow:0 18px 46px rgba(0,0,0,.5),0 0 0 1px rgba(240,200,136,.25);}
        .hero-logo-shine{position:absolute;inset:-4px;border-radius:50%;overflow:hidden;pointer-events:none;}
        .hero-logo-shine::after{content:"";position:absolute;top:-40%;left:-120%;width:55%;height:180%;background:linear-gradient(100deg,transparent,rgba(240,200,136,.55),transparent);transform:rotate(18deg);animation:heroShineSweep 4.6s ease-in-out infinite;animation-delay:1.3s;}
        @keyframes heroFloat{0%,100%{transform:translateY(0);}50%{transform:translateY(-10px);}}
        @keyframes heroLogoIn{to{opacity:1;transform:scale(1);}}
        @keyframes heroShineSweep{0%{left:-120%;}45%{left:130%;}100%{left:130%;}}
        @media (max-width:640px){.hero-logo-float{width:128px;height:128px;}}

        .hero-tagline-only{margin:0;}
        .hero-tagline-text{display:block;font-style:italic;font-weight:500;color:var(--gold-light);font-family:'Fraunces',serif;font-size:clamp(26px,4.4vw,42px);letter-spacing:.03em;}
        .btn{display:inline-block;padding:16px 40px;border:1.5px solid var(--gold);border-radius:var(--radius-pill);font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--cream);background:rgba(255,255,255,.06);backdrop-filter:blur(6px);transition:background .3s ease,color .3s ease,transform .25s ease,box-shadow .3s ease;}
        .btn:hover{background:var(--gold);color:var(--maroon-dark);transform:translateY(-2px);box-shadow:0 14px 30px rgba(217,164,65,.35);}
        .btn.solid{background:var(--gold);color:var(--maroon-dark);}
        .btn.solid:hover{background:var(--gold-light);}

        .divider{display:flex;align-items:center;justify-content:center;gap:18px;max-width:340px;margin:0 auto;padding:0 20px;}
        .divider-line{flex:1;height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent);}
        .divider.dark .divider-line{background:linear-gradient(90deg,transparent,var(--gold-light),transparent);}

        .intro{padding:110px 0 96px;text-align:center;}
        .intro .wrap{max-width:760px;}
        .intro h2{font-size:clamp(30px,4vw,44px);font-weight:600;margin:22px 0 30px;color:var(--maroon);}
        .intro p{font-size:17px;line-height:1.85;color:var(--ink-soft);margin:0 0 20px;}
        .intro .signoff{margin-top:38px;font-family:'Fraunces',serif;font-style:italic;font-size:22px;color:var(--maroon);}
        .intro .signoff strong{font-style:normal;font-weight:600;color:var(--gold);}

        .cat-pills-wrap{position:sticky;top:0;z-index:100;background:rgba(251,244,231,.85);backdrop-filter:blur(10px);border-bottom:1px solid rgba(110,31,43,.08);}
        .cat-pills{display:flex;gap:10px;overflow-x:auto;padding:16px 28px;max-width:1180px;margin:0 auto;}
        .cat-pills button{flex-shrink:0;padding:10px 22px;border:1.5px solid rgba(110,31,43,.2);background:#fff;font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--maroon);border-radius:var(--radius-pill);transition:.25s;white-space:nowrap;font-family:inherit;}
        .cat-pills button:hover{background:var(--maroon);color:var(--cream);border-color:var(--maroon);transform:translateY(-1px);box-shadow:0 8px 18px rgba(110,31,43,.2);}

        .load-error{background:#F6E1E1;border:1px solid rgba(163,50,60,.3);color:#A3323C;font-size:13px;padding:12px 16px;margin:20px auto 0;border-radius:2px;}

        .category{padding:90px 0;}
        .category.alt{background:var(--blush);}
        .category-head{text-align:center;max-width:560px;margin:0 auto 50px;}
        .category-head h2{font-size:clamp(32px,4.4vw,46px);color:var(--maroon);margin:0 0 12px;font-weight:600;}
        .category-head p{font-family:'Fraunces',serif;font-style:italic;color:var(--ink-soft);font-size:17px;margin:0;}

        .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:26px;}
        @media (max-width:1000px){.grid{grid-template-columns:repeat(3,1fr);}}
        @media (max-width:720px){.grid{grid-template-columns:repeat(2,1fr);gap:16px;}}
        @media (max-width:460px){.grid{grid-template-columns:1fr 1fr;gap:12px;}}

        .carousel-wrap{position:relative;}
        .carousel-track{display:flex;gap:22px;overflow-x:auto;scroll-snap-type:x proximity;padding:4px 4px 10px;scrollbar-width:none;-ms-overflow-style:none;}
        .carousel-track::-webkit-scrollbar{display:none;}
        .carousel-track .card{flex:0 0 auto;width:270px;scroll-snap-align:start;}
        @media (max-width:720px){.carousel-track .card{width:220px;}}
        @media (max-width:460px){.carousel-track .card{width:72vw;}}
        .carousel-arrow{position:absolute;top:38%;transform:translateY(-50%);z-index:6;width:44px;height:44px;border-radius:50%;background:#fff;box-shadow:var(--shadow-soft);border:1px solid rgba(110,31,43,.12);color:var(--maroon);display:flex;align-items:center;justify-content:center;transition:background .2s,transform .2s;}
        .carousel-arrow:hover{background:var(--maroon);color:#fff;transform:translateY(-50%) scale(1.06);}
        .carousel-arrow.left{left:-18px;}
        .carousel-arrow.right{right:-18px;}
        @media (max-width:640px){.carousel-arrow{width:36px;height:36px;}.carousel-arrow.left{left:-8px;}.carousel-arrow.right{right:-8px;}}

        .card{background:#fff;border:none;border-radius:var(--radius-md);overflow:hidden;box-shadow:var(--shadow-soft);display:flex;flex-direction:column;
          text-align:left;width:100%;padding:0;font-family:inherit;color:inherit;cursor:pointer;
          opacity:0;transform:translateY(22px);clip-path:inset(0 0 100% 0);
          transition:opacity .8s ease,clip-path 1s cubic-bezier(.22,.61,.36,1),transform .35s ease,box-shadow .35s ease;}
        .card.is-visible{opacity:1;transform:translateY(0);clip-path:inset(0 0 0% 0);}
        .card:hover{transform:translateY(-6px);box-shadow:var(--shadow-lift);}
        .card .thumb{aspect-ratio:4/5;overflow:hidden;background:var(--cream-deep);position:relative;}
        .card .thumb img{width:100%;height:100%;object-fit:cover;transition:transform 1.1s cubic-bezier(.22,.61,.36,1);}
        .card:hover .thumb img{transform:scale(1.08);}
        .card .thumb::before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 55%,rgba(43,33,29,.55) 100%);opacity:0;transition:opacity .35s ease;pointer-events:none;}
        .card:hover .thumb::before{opacity:1;}
        .card .thumb::after{content:"";position:absolute;top:0;left:-60%;width:35%;height:100%;
          background:linear-gradient(115deg,transparent,rgba(240,200,136,.55),transparent);
          transform:skewX(-18deg);transition:left 1s ease;pointer-events:none;}
        .card:hover .thumb::after{left:135%;}
        .photo-count{position:absolute;top:10px;right:10px;background:rgba(43,33,29,.65);color:var(--cream);font-size:10px;letter-spacing:.05em;padding:4px 8px;border-radius:999px;backdrop-filter:blur(2px);}
        .stock-badge{position:absolute;top:10px;left:10px;font-size:10px;letter-spacing:.05em;text-transform:uppercase;padding:5px 10px;border-radius:999px;font-weight:600;}
        .stock-badge.out{background:rgba(43,33,29,.85);color:#F0B8B8;}
        .stock-badge.low{background:rgba(217,164,65,.92);color:var(--maroon-dark);}
        .card .thumb img.is-out-of-stock{filter:grayscale(65%);opacity:.65;}
        .view-hint{position:absolute;left:50%;bottom:14px;transform:translate(-50%,10px);opacity:0;display:flex;align-items:center;gap:6px;background:rgba(255,255,255,.16);backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.3);color:#fff;font-size:11px;letter-spacing:.08em;text-transform:uppercase;padding:9px 16px;border-radius:var(--radius-pill);transition:opacity .3s ease,transform .3s ease;white-space:nowrap;}
        .card:hover .view-hint{opacity:1;transform:translate(-50%,0);}
        .card .info{padding:18px 18px 22px;text-align:center;}
        .card .info h3{margin:0 0 6px;font-size:19px;color:var(--ink);font-weight:600;}
        .card .info .price{font-size:13px;letter-spacing:.05em;color:var(--gold);font-family:'Jost',sans-serif;}
        .star-rating{display:flex;justify-content:center;gap:2px;margin:2px 0 8px;}
        .star-rating .star{color:rgba(110,31,43,.2);}
        .star-rating .star.filled{color:var(--gold);fill:var(--gold);}
        .star-picker{display:flex;gap:4px;}
        .star-btn{background:none;border:none;padding:2px;color:rgba(110,31,43,.28);transition:color .15s ease,transform .15s ease;}
        .star-btn:hover{transform:scale(1.12);color:var(--gold);}
        .star-btn.filled{color:var(--gold);}
        .star-btn.filled svg{fill:var(--gold);}

        .empty-state{grid-column:1/-1;border:1.5px dashed rgba(110,31,43,.25);border-radius:var(--radius-md);padding:56px 24px;text-align:center;color:var(--ink-soft);}
        .empty-state .glyph{font-family:'Fraunces',serif;font-size:34px;color:var(--gold);margin-bottom:10px;font-style:italic;}
        .empty-state p{margin:0;font-size:14px;letter-spacing:.02em;}

        .cta-band{position:relative;background:linear-gradient(160deg,var(--maroon) 0%,var(--maroon-dark) 100%);color:var(--cream);text-align:center;padding:90px 24px;overflow:hidden;}
        .cta-watermark{position:absolute;top:50%;left:50%;width:520px;height:520px;transform:translate(-50%,-50%);opacity:.05;pointer-events:none;animation:watermarkSpin 90s linear infinite;}
        @keyframes watermarkSpin{to{transform:translate(-50%,-50%) rotate(360deg);}}
        .cta-band h2{font-size:clamp(28px,4vw,40px);margin:0 0 16px;font-weight:600;}
        .cta-band p{font-family:'Fraunces',serif;font-style:italic;font-size:18px;color:var(--cream-deep);margin:0 0 30px;}

        footer{background:var(--ink);color:var(--cream-deep);padding:70px 0 26px;}
        .foot-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:50px;padding-bottom:46px;border-bottom:1px solid rgba(251,244,231,.12);}
        @media (max-width:720px){.foot-grid{grid-template-columns:1fr;gap:34px;}}
        footer h4{font-family:'Fraunces',serif;font-size:15px;letter-spacing:.1em;text-transform:uppercase;color:var(--gold);margin:0 0 18px;}
        .foot-brand-row{display:flex;align-items:center;gap:12px;margin-bottom:12px;}
        .foot-logo{width:40px;height:40px;border-radius:50%;flex-shrink:0;box-shadow:0 0 0 1px rgba(217,164,65,.4);}
        footer .foot-brand{font-family:'Fraunces',serif;font-size:26px;font-weight:600;color:var(--cream);margin:0;}
        footer .foot-brand em{color:var(--gold);font-style:italic;}
        footer p{font-size:14px;line-height:1.8;color:#C9BFB4;margin:0 0 10px;}
        footer ul{list-style:none;margin:0;padding:0;}
        footer ul li{margin-bottom:11px;}
        footer ul a{font-size:14px;color:#C9BFB4;transition:color .2s;}
        footer ul a:hover{color:var(--gold-light);}
        .foot-bottom{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;padding-top:24px;font-size:12px;color:#8B8074;}
        .foot-bottom .admin-link{background:none;border:none;cursor:pointer;font-family:inherit;color:#8B8074;letter-spacing:.06em;border-bottom:1px dotted #8B8074;padding:0;}
        .foot-bottom .admin-link:hover{color:var(--gold-light);}

        .wa-float{position:fixed;right:24px;bottom:24px;z-index:300;width:60px;height:60px;border-radius:50%;background:var(--whatsapp);display:flex;align-items:center;justify-content:center;box-shadow:0 8px 22px rgba(37,211,102,.45);transition:transform .25s ease;}
        .wa-float:hover{transform:scale(1.08);}
        .wa-float .ring{position:absolute;inset:0;border-radius:50%;border:2px solid var(--whatsapp);animation:wa-pulse 2.2s ease-out infinite;}
        @keyframes wa-pulse{0%{transform:scale(1);opacity:.6;}100%{transform:scale(1.7);opacity:0;}}
        @media (prefers-reduced-motion:reduce){.wa-float .ring{animation:none;display:none;}}
        @media (max-width:480px){.wa-float{width:52px;height:52px;right:16px;bottom:16px;}}

        .modal-overlay{position:fixed;inset:0;background:rgba(43,33,29,.7);display:none;align-items:flex-start;justify-content:center;z-index:500;padding:40px 20px;overflow-y:auto;}
        .modal-overlay.open{display:flex;}
        .modal{background:var(--cream);max-width:640px;width:100%;max-height:88vh;overflow-y:auto;border-top:3px solid var(--gold);border-radius:var(--radius-lg);position:relative;box-shadow:var(--shadow-lift);}
        .modal-head{display:flex;align-items:center;justify-content:space-between;padding:22px 28px;border-bottom:1px solid rgba(110,31,43,.12);}
        .modal-head h3{margin:0;color:var(--maroon);font-size:24px;}
        .modal-close{background:none;border:none;color:var(--ink-soft);padding:4px;display:flex;}
        .modal-close:hover{color:var(--maroon);}
        .modal-body{padding:26px 28px 32px;}

        /* ---- Product detail / gallery modal ---- */
        .detail-modal{max-width:920px;position:relative;overflow:hidden;border-radius:var(--radius-lg);}
        .detail-scroll{max-height:calc(100vh - 80px);overflow-y:auto;display:grid;grid-template-columns:1.15fr 1fr;}
        @media (max-width:760px){.detail-scroll{grid-template-columns:1fr;}}
        .detail-close{position:absolute;top:14px;right:14px;background:rgba(43,33,29,.55);color:#fff;border-radius:50%;z-index:5;padding:6px;}
        .detail-close:hover{background:rgba(43,33,29,.8);color:var(--gold-light);}
        .detail-share{position:absolute;top:14px;right:60px;background:rgba(43,33,29,.55);color:#fff;border-radius:var(--radius-pill);z-index:5;padding:6px 12px;font-size:11px;display:flex;align-items:center;gap:5px;white-space:nowrap;}
        .detail-share:hover{background:rgba(43,33,29,.8);color:var(--gold-light);}
        .detail-gallery{background:var(--ink);display:flex;flex-direction:column;}
        .detail-main-image{position:relative;aspect-ratio:4/5;background:var(--ink);}
        .detail-main-image img{width:100%;height:100%;object-fit:cover;}
        .zoom-hint{position:absolute;top:10px;left:10px;display:flex;align-items:center;gap:5px;background:rgba(0,0,0,.5);color:#fff;font-size:10px;letter-spacing:.05em;text-transform:uppercase;padding:6px 11px;border-radius:var(--radius-pill);cursor:zoom-in;backdrop-filter:blur(4px);}
        .gallery-arrow{position:absolute;top:50%;transform:translateY(-50%);background:rgba(0,0,0,.4);color:#fff;border:none;border-radius:50%;width:38px;height:38px;display:flex;align-items:center;justify-content:center;transition:background .2s;}
        .gallery-arrow:hover{background:rgba(0,0,0,.65);}
        .gallery-arrow.left{left:12px;}
        .gallery-arrow.right{right:12px;}
        .gallery-counter{position:absolute;bottom:10px;right:12px;background:rgba(0,0,0,.5);color:#fff;font-size:11px;padding:4px 10px;border-radius:999px;}
        .thumb-strip{display:flex;gap:8px;padding:10px;overflow-x:auto;background:var(--ink);}
        .thumb-strip-item{flex-shrink:0;width:56px;height:56px;padding:0;border:2px solid transparent;border-radius:var(--radius-sm);overflow:hidden;opacity:.55;transition:opacity .2s,border-color .2s;background:none;}
        .thumb-strip-item img{width:100%;height:100%;object-fit:cover;}
        .thumb-strip-item.active,.thumb-strip-item:hover{opacity:1;border-color:var(--gold);}

        /* ---- Fullscreen image lightbox / zoom ---- */
        .lightbox-overlay{position:fixed;inset:0;z-index:700;background:rgba(15,9,6,.94);display:flex;align-items:center;justify-content:center;}
        .lightbox-scroll{width:100%;height:100%;overflow:auto;display:flex;align-items:center;justify-content:center;padding:60px 20px;}
        .lightbox-scroll img{max-width:90vw;max-height:82vh;object-fit:contain;cursor:zoom-in;transition:transform .3s ease;border-radius:4px;}
        .lightbox-scroll img.zoomed{max-width:none;max-height:none;width:auto;height:220vh;cursor:zoom-out;}
        .lightbox-close{position:absolute;top:20px;right:20px;z-index:5;background:rgba(255,255,255,.12);color:#fff;border:1px solid rgba(255,255,255,.25);border-radius:50%;width:42px;height:42px;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(6px);}
        .lightbox-close:hover{background:rgba(255,255,255,.22);}
        .lightbox-arrow{position:absolute;top:50%;transform:translateY(-50%);z-index:5;background:rgba(255,255,255,.12);color:#fff;border:1px solid rgba(255,255,255,.25);border-radius:50%;width:48px;height:48px;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(6px);}
        .lightbox-arrow:hover{background:rgba(255,255,255,.22);}
        .lightbox-arrow.left{left:20px;}
        .lightbox-arrow.right{right:20px;}
        .lightbox-counter{position:absolute;top:24px;left:50%;transform:translateX(-50%);background:rgba(255,255,255,.12);color:#fff;font-size:12px;padding:6px 14px;border-radius:var(--radius-pill);backdrop-filter:blur(6px);}
        .lightbox-zoom-toggle{position:absolute;bottom:26px;left:50%;transform:translateX(-50%);background:var(--gold);color:var(--maroon-dark);border:none;font-size:11px;letter-spacing:.1em;text-transform:uppercase;font-weight:600;padding:11px 22px;border-radius:var(--radius-pill);display:flex;align-items:center;gap:7px;box-shadow:var(--shadow-lift);}
        .lightbox-zoom-toggle:hover{background:var(--gold-light);}
        @media (max-width:640px){.lightbox-arrow{width:38px;height:38px;}.lightbox-arrow.left{left:8px;}.lightbox-arrow.right{right:8px;}}
        .detail-info{padding:32px 30px;display:flex;flex-direction:column;}
        .detail-info h3{font-size:28px;color:var(--maroon);margin:0 0 10px;font-weight:600;}
        .detail-price{font-size:16px;color:var(--gold);letter-spacing:.04em;margin:6px 0 6px;font-weight:500;}
        .detail-stock{display:inline-block;font-size:11px;letter-spacing:.06em;text-transform:uppercase;font-weight:600;padding:5px 12px;border-radius:999px;margin-bottom:18px;width:fit-content;}
        .detail-stock.in{background:rgba(47,122,75,.12);color:#2F7A4B;}
        .detail-stock.low{background:rgba(217,164,65,.18);color:#8A6417;}
        .detail-stock.out{background:rgba(163,50,60,.12);color:#A3323C;}
        .detail-description{font-size:14.5px;line-height:1.85;color:var(--ink-soft);margin:0 0 26px;white-space:pre-line;}
        .detail-description.muted{font-style:italic;opacity:.7;}
        .detail-wa{margin-top:auto;text-align:center;}

        .field{margin-bottom:18px;}
        .field label{display:block;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-soft);margin-bottom:7px;}
        .field input[type=text],.field input[type=password],.field input[type=number],.field select,.field textarea{width:100%;padding:12px 14px;border:1.5px solid rgba(110,31,43,.18);border-radius:var(--radius-sm);background:#fff;font-family:'Jost',sans-serif;font-size:14px;color:var(--ink);transition:border-color .2s;}
        .field textarea{resize:vertical;min-height:70px;}
        .field input:focus,.field select:focus,.field textarea:focus{border-color:var(--gold);box-shadow:0 0 0 3px rgba(217,164,65,.15);}
        .file-drop{border:1.5px dashed rgba(110,31,43,.3);border-radius:var(--radius-sm);padding:22px;text-align:center;cursor:pointer;font-size:13px;color:var(--ink-soft);position:relative;display:flex;flex-direction:column;align-items:center;gap:8px;}
        .file-drop input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%;height:100%;}
        .photo-preview-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:10px;}
        .photo-preview-item{position:relative;aspect-ratio:1/1;border-radius:var(--radius-sm);overflow:hidden;background:var(--cream-deep);}
        .photo-preview-item img{width:100%;height:100%;object-fit:cover;}
        .photo-remove{position:absolute;top:3px;right:3px;background:rgba(43,33,29,.7);color:#fff;border:none;border-radius:50%;width:20px;height:20px;display:flex;align-items:center;justify-content:center;}
        .photo-remove:hover{background:#A3323C;}
        .form-msg{font-size:13px;margin-top:4px;min-height:18px;}
        .form-msg.error{color:#A3323C;}
        .form-msg.success{color:#2F7A4B;}
        .admin-submit{width:100%;padding:15px;background:var(--maroon);color:var(--cream);border:none;border-radius:var(--radius-pill);font-size:12px;letter-spacing:.14em;text-transform:uppercase;transition:background .2s,transform .2s;}
        .admin-submit:hover{background:var(--maroon-dark);transform:translateY(-1px);}
        .admin-submit:disabled{opacity:.6;cursor:default;}

        .admin-dash-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;}
        .logout-link{font-size:12px;color:var(--ink-soft);border-bottom:1px dotted var(--ink-soft);background:none;border-top:none;border-left:none;border-right:none;display:flex;align-items:center;gap:5px;padding:0;font-family:inherit;}
        .logout-link:hover{color:var(--maroon);}

        .manage-list{margin-top:30px;border-top:1px solid rgba(110,31,43,.12);padding-top:20px;}
        .manage-list h4{font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-soft);margin:0 0 14px;}
        .manage-item{display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid rgba(110,31,43,.08);}
        .manage-item img{width:46px;height:46px;object-fit:cover;flex-shrink:0;border-radius:var(--radius-sm);}
        .manage-item .mi-info{flex:1;min-width:0;}
        .manage-item .mi-info .t{font-size:14px;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
        .manage-item .mi-info .c{font-size:11px;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em;}
        .manage-item .del{background:none;border:1px solid rgba(163,50,60,.4);border-radius:var(--radius-pill);color:#A3323C;font-size:11px;padding:6px 12px;letter-spacing:.05em;text-transform:uppercase;flex-shrink:0;display:flex;align-items:center;gap:5px;}
        .manage-item .del:hover{background:#A3323C;color:#fff;}
        .stock-stepper{display:flex;align-items:center;gap:8px;flex-shrink:0;border:1px solid rgba(110,31,43,.2);border-radius:999px;padding:3px 4px;}
        .stock-stepper button{width:22px;height:22px;border-radius:50%;border:none;background:var(--blush);color:var(--maroon);font-size:15px;line-height:1;display:flex;align-items:center;justify-content:center;}
        .stock-stepper button:hover:not(:disabled){background:var(--gold);color:var(--maroon-dark);}
        .stock-stepper button:disabled{opacity:.35;cursor:default;}
        .stock-stepper span{min-width:20px;text-align:center;font-size:12px;font-weight:600;color:var(--ink);}
        .stock-stepper.out span{color:#A3323C;}
        .stock-stepper.low span{color:#8A6417;}
        .manage-empty{font-size:13px;color:var(--ink-soft);padding:10px 0;}
        .storage-note{font-size:12px;color:var(--ink-soft);background:var(--blush);border-left:3px solid var(--gold);border-radius:var(--radius-sm);padding:12px 16px;margin-top:22px;line-height:1.6;}

        @media (prefers-reduced-motion: reduce){
          .alif-root *{animation:none!important;transition:none!important;}
          .card{opacity:1!important;transform:none!important;clip-path:none!important;}
        }
      `}</style>

      {/* ================= HEADER ================= */}
      <header className={"site" + (scrolled ? " scrolled" : "")}>
        <div className="wrap">
          <button className="brand" style={{ background: "none", border: "none", padding: 0 }} onClick={() => scrollToId("top")}>
            <img src={LOGO_SRC} alt="ALIF Traditional" className="brand-logo" />
            <span className="brand-name">ALIF <em>Traditional</em></span>
          </button>
          <nav className={"main-nav" + (mobileNavOpen ? " open" : "")}>
            <button className="nav-link" onClick={() => scrollToId("top")}>Home</button>
            <button className="nav-link" onClick={() => scrollToId("about")}>Our Story</button>
            <button className="nav-link" onClick={() => scrollToId("clothes-brand")}>Collections</button>
            <button className="nav-link" onClick={() => scrollToId("contact")}>Contact</button>
          </nav>
          <button className="nav-toggle" aria-label="Toggle menu" onClick={() => setMobileNavOpen((v) => !v)}>
            {mobileNavOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>
      </header>

      {/* ================= HERO ================= */}
      <section className="hero" id="top">
        <video className="hero-video" autoPlay muted loop playsInline poster={LOGO_SRC}>
          <source src={VIDEO_SRC} type="video/mp4" />
        </video>
        <div className="hero-scrim" aria-hidden="true"></div>

        <div className="hero-inner">
          <div className="hero-logo-float">
            <div className="hero-logo-shine" aria-hidden="true"></div>
            <img src={LOGO_SRC} alt="ALIF Traditional emblem" className="hero-logo" />
          </div>
          <h1 className="hero-tagline-only"><span className="hero-tagline-text">Where Tradition Meets Elegance</span></h1>
          <p className="tag">Welcome to a collection where timeless craft meets modern comfort.</p>
          <button className="btn" onClick={() => scrollToId("clothes-brand")}>Explore The Collections</button>
        </div>

        <button className="scroll-cue" onClick={() => scrollToId("about")} aria-label="Scroll down">
          <ChevronDown size={20} />
        </button>
      </section>

      {/* ================= INTRO ================= */}
      <section className="intro" id="about">
        <div className="wrap">
          <span className="eyebrow">Our Story</span>
          <h2>Tradition never goes out of style.</h2>
          <p>At ALIF Traditional, our collection is thoughtfully curated to blend timeless elegance with modern comfort and premium quality.</p>
          <p>Whether you're searching for beautifully embroidered suits, graceful dupattas, elegant shawls, stylish handbags, or luxurious bedsheets, every piece is carefully selected to help you look and feel your best.</p>
          <p>Customer satisfaction, trusted quality, and timeless designs are at the heart of everything we do. We are committed to bringing you products that celebrate tradition while adding beauty, style, and comfort to your everyday life.</p>
          <Divider />
          <p className="signoff">✨ <strong>ALIF Traditional</strong> — Where Tradition Meets Elegance.</p>
        </div>
      </section>

      {/* ================= CATEGORY PILLS ================= */}
      <div className="cat-pills-wrap">
        <div className="cat-pills">
          {CATEGORIES.map((c) => (
            <button key={c.id} onClick={() => scrollToId(c.id)}>{c.label}</button>
          ))}
        </div>
      </div>

      {loadError && (
        <div className="load-error wrap">
          Couldn't reach the product server. Make sure the backend is running (see README) and refresh.
        </div>
      )}

      {/* ================= CATEGORY SECTIONS ================= */}
      {CATEGORIES.map((c) => {
        const items = itemsFor(c.label).slice(0, 10);
        return (
          <section className={"category" + (c.alt ? " alt" : "")} id={c.id} key={c.id}>
            <div className="wrap">
              <div className="category-head">
                <span className="eyebrow">Collection</span>
                <h2>{c.label}</h2>
                <p>{c.tagline}</p>
              </div>
              {loadingProducts ? (
                <div className="grid"><div className="empty-state"><div className="glyph">✦</div><p>Loading the collection…</p></div></div>
              ) : items.length === 0 ? (
                <div className="grid"><div className="empty-state"><div className="glyph">✦</div><p>New pieces coming soon to this collection.</p></div></div>
              ) : (
                <div className="carousel-wrap">
                  <button className="carousel-arrow left" onClick={() => scrollCarousel(c.id, -1)} aria-label="Scroll left"><ChevronLeft size={20} /></button>
                  <div className="carousel-track" ref={(el) => { carouselRefs.current[c.id] = el; }}>
                    {items.map((p, idx) => (
                      <div
                        className="card"
                        key={p.id}
                        role="button"
                        tabIndex={0}
                        style={{ transitionDelay: (idx % 4) * 90 + "ms" }}
                        onClick={() => openDetail(p)}
                        onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openDetail(p); } }}
                      >
                        <div className="thumb">
                          <img src={p.images && p.images[0]} alt={p.title} loading="lazy" className={stockStatus(p.stock) === "out" ? "is-out-of-stock" : ""} />
                          {p.images && p.images.length > 1 ? <span className="photo-count">{p.images.length} photos</span> : null}
                          <StockBadge stock={p.stock} />
                          <span className="view-hint"><Eye size={14} /> View details</span>
                        </div>
                        <div className="info">
                          <h3>{p.title}</h3>
                          <StarRating value={p.rating} />
                          {p.price ? <div className="price">{p.price}</div> : null}
                        </div>
                      </div>
                    ))}
                  </div>
                  <button className="carousel-arrow right" onClick={() => scrollCarousel(c.id, 1)} aria-label="Scroll right"><ChevronRight size={20} /></button>
                </div>
              )}
            </div>
          </section>
        );
      })}

      {/* ================= CTA BAND ================= */}
      <section className="cta-band" id="contact">
        <img src={LOGO_SRC} alt="" className="cta-watermark" aria-hidden="true" />
        <Divider dark />
        <h2>Have a question about a piece?</h2>
        <p>Message us directly on WhatsApp — we reply with fabric, size and price details.</p>
        <a className="btn solid" href={`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent("Hello ALIF Traditional, I'd like to ask about a product.")}`} target="_blank" rel="noopener noreferrer">
          Chat on WhatsApp
        </a>
      </section>

      {/* ================= FOOTER ================= */}
      <footer>
        <div className="wrap">
          <div className="foot-grid">
            <div>
              <div className="foot-brand-row">
                <img src={LOGO_SRC} alt="" className="foot-logo" />
                <p className="foot-brand">ALIF <em>Traditional</em></p>
              </div>
              <p>Thoughtfully curated pieces that blend timeless elegance with modern comfort and premium quality — for the way you live today.</p>
            </div>
            <div>
              <h4>Collections</h4>
              <ul>
                {CATEGORIES.map((c) => (
                  <li key={c.id}><button className="nav-link" style={{ background: "none", border: "none", padding: 0, font: "inherit", color: "inherit", cursor: "pointer" }} onClick={() => scrollToId(c.id)}>{c.label}</button></li>
                ))}
              </ul>
            </div>
            <div>
              <h4>Get in touch</h4>
              <ul>
                <li><a href={`https://wa.me/${WHATSAPP_NUMBER}`} target="_blank" rel="noopener noreferrer">WhatsApp: +{WHATSAPP_NUMBER}</a></li>
                <li><a href="mailto:hello@aliftraditional.com">hello@aliftraditional.com</a></li>
                <li>Karachi, Pakistan</li>
              </ul>
            </div>
          </div>
          <div className="foot-bottom">
            <span>© {new Date().getFullYear()} ALIF Traditional. All rights reserved.</span>
            <button className="admin-link" onClick={openAdmin}>Admin Portal</button>
          </div>
        </div>
      </footer>

      {/* ================= WHATSAPP FLOAT ================= */}
      <a className="wa-float" href={`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent("Hello ALIF Traditional")}`} target="_blank" rel="noopener noreferrer" aria-label="Chat with us on WhatsApp">
        <span className="ring" aria-hidden="true"></span>
        <WhatsAppIcon />
      </a>

      {/* ================= PRODUCT DETAIL MODAL ================= */}
      <div className={"modal-overlay" + (selectedProduct ? " open" : "")} onClick={(e) => { if (e.target === e.currentTarget) closeDetail(); }}>
        {selectedProduct && (
          <div className="modal detail-modal" role="dialog" aria-modal="true">
            <button className="modal-close detail-close" onClick={closeDetail} aria-label="Close"><X size={22} /></button>
            <button
              className="modal-close detail-share"
              aria-label="Copy link to this product"
              onClick={() => {
                const url = `${window.location.origin}${window.location.pathname}#product-${selectedProduct.id}`;
                navigator.clipboard?.writeText(url);
                setLinkCopied(true);
                setTimeout(() => setLinkCopied(false), 2000);
              }}
            >
              {linkCopied ? "Copied!" : <Share2 size={18} />}
            </button>
            <div className="detail-scroll">
              <div className="detail-gallery">
                <div className="detail-main-image">
                  <img src={selectedProduct.images[galleryIndex]} alt={selectedProduct.title} onClick={openLightbox} style={{ cursor: "zoom-in" }} />
                  <span className="zoom-hint" onClick={openLightbox} aria-hidden="true"><ZoomIn size={14} /> Click to zoom</span>
                  {selectedProduct.images.length > 1 && (
                    <>
                      <button className="gallery-arrow left" onClick={prevImage} aria-label="Previous photo"><ChevronLeft size={22} /></button>
                      <button className="gallery-arrow right" onClick={nextImage} aria-label="Next photo"><ChevronRight size={22} /></button>
                      <span className="gallery-counter">{galleryIndex + 1} / {selectedProduct.images.length}</span>
                    </>
                  )}
                </div>
                {selectedProduct.images.length > 1 && (
                  <div className="thumb-strip">
                    {selectedProduct.images.map((img, i) => (
                      <button key={i} className={"thumb-strip-item" + (i === galleryIndex ? " active" : "")} onClick={() => setGalleryIndex(i)}>
                        <img src={img} alt="" />
                      </button>
                    ))}
                  </div>
                )}
              </div>
              <div className="detail-info">
                <span className="eyebrow">{selectedProduct.category}</span>
                <h3>{selectedProduct.title}</h3>
                <StarRating value={selectedProduct.rating} size={17} />
                {selectedProduct.price ? <div className="detail-price">{selectedProduct.price}</div> : null}
                <div className={"detail-stock " + stockStatus(selectedProduct.stock)}>
                  {stockStatus(selectedProduct.stock) === "out" && "Out of Stock"}
                  {stockStatus(selectedProduct.stock) === "low" && `Only ${selectedProduct.stock} left in stock`}
                  {stockStatus(selectedProduct.stock) === "in" && "In Stock"}
                </div>
                {selectedProduct.description ? (
                  <p className="detail-description">{selectedProduct.description}</p>
                ) : (
                  <p className="detail-description muted">No description added for this piece yet.</p>
                )}
                {(selectedProduct.material || selectedProduct.design) && (
                  <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 14 }}>
                    {selectedProduct.material && (
                      <span className="stock-badge" style={{ position: "static", background: "var(--blush)", color: "var(--maroon)" }}>
                        {selectedProduct.material}
                      </span>
                    )}
                    {selectedProduct.design && (
                      <span className="stock-badge" style={{ position: "static", background: "var(--blush)", color: "var(--maroon)" }}>
                        {selectedProduct.design}
                      </span>
                    )}
                  </div>
                )}
                <a
                  className="btn solid detail-wa"
                  href={`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(
                    (stockStatus(selectedProduct.stock) === "out"
                      ? `Hello ALIF Traditional, is "${selectedProduct.title}" going to be restocked?`
                      : `Hello ALIF Traditional, I'm interested in "${selectedProduct.title}"${selectedProduct.price ? ` (${selectedProduct.price})` : ""}.`) +
                    `\n\nHere's the product: ${window.location.origin}${window.location.pathname}#product-${selectedProduct.id}`
                  )}`}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  {stockStatus(selectedProduct.stock) === "out" ? "Ask About Restock" : "Ask about this on WhatsApp"}
                </a>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* ================= IMAGE LIGHTBOX / ZOOM ================= */}
      {lightboxOpen && selectedProduct && (
        <div className="lightbox-overlay" onClick={(e) => { if (e.target === e.currentTarget) closeLightbox(); }}>
          <button className="lightbox-close" onClick={closeLightbox} aria-label="Close zoom"><X size={24} /></button>
          {selectedProduct.images.length > 1 && (
            <>
              <button className="lightbox-arrow left" onClick={(e) => { e.stopPropagation(); prevImage(); }} aria-label="Previous photo"><ChevronLeft size={26} /></button>
              <button className="lightbox-arrow right" onClick={(e) => { e.stopPropagation(); nextImage(); }} aria-label="Next photo"><ChevronRight size={26} /></button>
              <span className="lightbox-counter">{galleryIndex + 1} / {selectedProduct.images.length}</span>
            </>
          )}
          <div className="lightbox-scroll">
            <img
              src={selectedProduct.images[galleryIndex]}
              alt={selectedProduct.title}
              className={zoomedIn ? "zoomed" : ""}
              onClick={() => setZoomedIn((z) => !z)}
            />
          </div>
          <button className="lightbox-zoom-toggle" onClick={() => setZoomedIn((z) => !z)}>
            {zoomedIn ? <><ZoomOut size={15} /> Zoom Out</> : <><ZoomIn size={15} /> Zoom In</>}
          </button>
        </div>
      )}

      {/* ================= ADMIN MODAL ================= */}
      <div className={"modal-overlay" + (adminOpen ? " open" : "")} onClick={(e) => { if (e.target === e.currentTarget) closeAdmin(); }}>
        <div className="modal" role="dialog" aria-modal="true">
          <div className="modal-head">
            <h3>Admin Portal</h3>
            <button className="modal-close" onClick={closeAdmin} aria-label="Close"><X size={22} /></button>
          </div>
          <div className="modal-body">
            {!isAdmin ? (
              <div>
                <div className="field">
                  <label htmlFor="adminPass">Password</label>
                  <input
                    type="password"
                    id="adminPass"
                    autoComplete="current-password"
                    placeholder="Enter admin password"
                    value={passwordInput}
                    onChange={(e) => setPasswordInput(e.target.value)}
                    onKeyDown={(e) => { if (e.key === "Enter") handleLogin(); }}
                  />
                </div>
                <div className="form-msg error">{loginError}</div>
                <button className="admin-submit" onClick={handleLogin} disabled={loggingIn}>{loggingIn ? "Checking…" : "Log In"}</button>
                {/* <p className="storage-note">Demo password: <strong>alif2026</strong> (matches ADMIN_KEY in the server's .env). Change it there before this goes live.</p> */}
              </div>
            ) : (
              <div>


                <div id="adminFormTop" className="admin-dash-head">
                  <span className="eyebrow" style={{ margin: 0 }}>
                    {editingId ? "Edit product" : "Add a product"}
                  </span>
                  <button className="logout-link" onClick={handleLogout}><LogOut size={13} /> Log out</button>
                </div>


                <form onSubmit={handleSubmit}>
                  <div className="field">
                    <label htmlFor="pCategory">Category</label>
                    <select id="pCategory" value={pCategory} onChange={(e) => setPCategory(e.target.value)}>
                      {CATEGORIES.map((c) => <option key={c.id} value={c.label}>{c.label}</option>)}
                    </select>
                  </div>
                  <div className="field">
                    <label htmlFor="pTitle">Product name</label>
                    <input type="text" id="pTitle" placeholder="e.g. Emerald Chikankari Suit" value={pTitle} onChange={(e) => setPTitle(e.target.value)} />
                  </div>
                  <div className="field">
                    <label htmlFor="pDescription">Description (optional)</label>
                    <textarea
                      id="pDescription"
                      rows={3}
                      placeholder="Fabric, fit, occasion, care instructions…"
                      value={pDescription}
                      onChange={(e) => setPDescription(e.target.value)}
                    />
                  </div>
                  <div className="field">
                    <label htmlFor="pPrice">Price (optional)</label>
                    <input type="text" id="pPrice" placeholder="e.g. Rs. 4,500" value={pPrice} onChange={(e) => setPPrice(e.target.value)} />
                  </div>
                  <div className="field">
                    <label>Rating (optional)</label>
                    <StarPicker value={pRating} onChange={setPRating} />
                  </div>
                  <div className="field">
                    <label htmlFor="pStock">Stock quantity</label>
                    <input
                      type="number"
                      id="pStock"
                      min="0"
                      step="1"
                      placeholder="0"
                      value={pStock}
                      onChange={(e) => setPStock(e.target.value)}
                    />
                  </div>
                  <div className="field">
                    <label htmlFor="pMaterial">Material (optional)</label>
                    <input
                      type="text"
                      id="pMaterial"
                      placeholder="e.g. Lawn, Pure Cotton, Silk Blend"
                      value={pMaterial}
                      onChange={(e) => setPMaterial(e.target.value)}
                    />
                  </div>
                  <div className="field">
                    <label htmlFor="pDesign">Design (optional)</label>
                    <input
                      type="text"
                      id="pDesign"
                      placeholder="e.g. Hand Embroidered, Digital Print, Chikankari"
                      value={pDesign}
                      onChange={(e) => setPDesign(e.target.value)}
                    />
                  </div>
                  <div className="field">
                    <label>Photos ({pImages.length}/{MAX_PHOTOS})</label>
                    {pImages.length > 0 && (
                      <div className="photo-preview-grid">
                        {pImages.map((img, i) => (
                          <div className="photo-preview-item" key={i}>
                            <img src={img} alt="" />
                            <button type="button" className="photo-remove" onClick={() => removeImageAt(i)} aria-label="Remove photo"><X size={13} /></button>
                          </div>
                        ))}
                      </div>
                    )}
                    {pImages.length < MAX_PHOTOS && (
                      <div className="file-drop">
                        <ImagePlus size={20} />
                        <span>Click to add photo{pImages.length > 0 ? "s" : ""} (JPG/PNG, up to {MAX_PHOTOS} total)</span>
                        <input ref={fileInputRef} type="file" accept="image/*" multiple onChange={handleFilesChange} />
                      </div>
                    )}
                    {imageError ? <div className="form-msg error">{imageError}</div> : null}
                  </div>
                  {formMsg ? <div className={"form-msg " + formMsg.type}>{formMsg.text}</div> : <div className="form-msg"></div>}
                  <div style={{ display: "flex", gap: 10 }}>
                    <button type="submit" className="admin-submit" disabled={saving}>
                      {saving ? "Saving…" : editingId ? "Save Changes" : "Add Product"}
                    </button>
                    {editingId && (
                      <button type="button" className="admin-submit" style={{ background: "var(--ink-soft)" }} onClick={resetForm}>
                        Cancel Edit
                      </button>
                    )}
                  </div>
                </form>

                <div className="manage-list">
                  <h4>Manage uploaded products ({products.length})</h4>
                  {products.length === 0 ? (
                    <p className="manage-empty">No products uploaded yet.</p>
                  ) : (
                    products.slice().reverse().map((p) => (
                      <div className="manage-item" key={p.id}>
                        <img src={p.images && p.images[0]} alt="" />
                        <div className="mi-info">
                          <div className="t">{p.title}</div>
                          <div className="c">{p.category} · {p.images ? p.images.length : 0} photo{p.images && p.images.length === 1 ? "" : "s"}</div>
                        </div>
                        <div className={"stock-stepper " + stockStatus(p.stock)}>
                          <button type="button" onClick={() => handleAdjustStock(p, -1)} aria-label="Decrease stock" disabled={(Number(p.stock) || 0) <= 0}>–</button>
                          <span>{p.stock ?? 0}</span>
                          <button type="button" onClick={() => handleAdjustStock(p, 1)} aria-label="Increase stock">+</button>
                        </div>
                        <button className="del" style={{ borderColor: "rgba(217,164,65,.5)", color: "var(--maroon)" }} onClick={() => startEdit(p)}>
                          Edit
                        </button>
                        <button className="del" onClick={() => handleDelete(p)}><Trash2 size={13} /> Remove</button>
                      </div>
                    ))
                  )}
                </div>

                <p className="storage-note">Products live in your MongoDB Atlas database, so every visitor sees the same catalog. Anyone with the admin password can add or remove products.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
